require_once __DIR__.'/../../includes/respaldo.php';exigir_rol('administrador');validar_post_csrf();$db=obtener_conexion();$error='';$ok='';
if(isset($_GET['descargar'])){try{$ruta=ruta_respaldo_segura((string)$_GET['descargar']);if(!is_file($ruta))throw new InvalidArgumentException('Respaldo no encontrado.');registrar_bitacora('respaldo_descargado',basename($ruta));header('Content-Type: application/sql');header('Content-Disposition: attachment; filename="'.basename($ruta).'"');header('Content-Length: '.filesize($ruta));readfile($ruta);exit;}catch(Throwable $e){$error='No se pudo descargar el respaldo.';}}
if($_SERVER['REQUEST_METHOD']==='POST'){try{$accion=(string)($_POST['accion']??'');if($accion==='crear'){$nombre=crear_respaldo($db);registrar_bitacora('respaldo_creado',$nombre);$ok='Respaldo generado: '.$nombre;}elseif($accion==='restaurar'){$nombre=(string)($_POST['nombre']??'');restaurar_respaldo($db,$nombre);registrar_bitacora('respaldo_restaurado',$nombre);$ok='Respaldo restaurado correctamente.';}elseif($accion==='eliminar'){$ruta=ruta_respaldo_segura((string)$_POST['nombre']);if(!is_file($ruta))throw new InvalidArgumentException('Respaldo no encontrado.');unlink($ruta);registrar_bitacora('respaldo_eliminado',basename($ruta));$ok='Respaldo eliminado.';}}catch(Throwable $e){$error=$e instanceof InvalidArgumentException?$e->getMessage():'No se pudo completar la operación solicitada.';}}
$respaldos=respaldos_existentes();$titulo='Copias de seguridad';require __DIR__.'/../../includes/header.php';?>
